#!/usr/bin/env node
/**
 * Import Course to Registry-Aligned Database
 *
 * Imports course content from VFS JSON files to the new registry-aligned schema.
 * Uses the new schema from 002_registry_schema.sql with:
 *   - UUID primary keys (auto-generated by Supabase)
 *   - Tables: courses, course_seeds, course_legos, course_practice_phrases
 *   - NO phrase_type column (computed at runtime from word_count/lego_count/position)
 *
 * Usage:
 *   node database/import-course-registry.cjs <course_code> [--dry-run]
 *
 * Examples:
 *   node database/import-course-registry.cjs spa_for_eng_v2 --dry-run
 *   node database/import-course-registry.cjs spa_for_eng_v2
 *
 * Input files (from public/vfs/courses/{course_code}/):
 *   - lego_pairs.json      - LEGO definitions with is_new flags
 *   - lego_baskets.json    - Practice phrases for new LEGOs
 *   - course_manifest.json - Course metadata (optional)
 *
 * Key features:
 *   - Idempotent: Uses upsert with ON CONFLICT for safe re-runs
 *   - Validates: Counts expected vs actual inserts
 *   - Calculates: word_count, lego_count, position for practice phrases
 *   - Handles: M-type LEGO components as JSONB
 */

require('dotenv').config();
const fs = require('fs-extra');
const path = require('path');
const { createClient } = require('@supabase/supabase-js');

// =============================================================================
// CONFIG
// =============================================================================

const VFS_COURSES = path.join(__dirname, '..', 'public', 'vfs', 'courses');

// Initialize Supabase client
const supabase = createClient(
  process.env.SUPABASE_URL,
  process.env.SUPABASE_SERVICE_KEY,
  {
    auth: {
      persistSession: false,
      autoRefreshToken: false,
      detectSessionInUrl: false
    }
  }
);

// =============================================================================
// HELPER FUNCTIONS
// =============================================================================

/**
 * Parse seed number from seed_id (e.g., "S0001" → 1)
 */
function parseSeedNumber(seedId) {
  const match = seedId.match(/S(\d+)/i);
  if (!match) {
    throw new Error(`Invalid seed_id format: ${seedId}`);
  }
  return parseInt(match[1], 10);
}

/**
 * Parse lego index from lego_id (e.g., "S0001L02" → 2)
 */
function parseLegoIndex(legoId) {
  const match = legoId.match(/L(\d+)$/i);
  if (!match) {
    throw new Error(`Invalid lego_id format: ${legoId}`);
  }
  return parseInt(match[1], 10);
}

/**
 * Count words in a text string (simple whitespace split)
 */
function countWords(text) {
  return text.trim().split(/\s+/).length;
}

/**
 * Extract known_lang and target_lang from course_code
 * Handles version suffixes like _v2, _test, etc.
 * Examples:
 *   "spa_for_eng" → { known_lang: "eng", target_lang: "spa" }
 *   "spa_for_eng_v2" → { known_lang: "eng", target_lang: "spa" }
 */
function parseLanguagesFromCourseCode(courseCode) {
  // Match pattern: {target}_for_{known} with optional suffix
  const match = courseCode.match(/^([a-z]{3})_for_([a-z]{3})(?:_.*)?$/);
  if (!match) {
    throw new Error(`Invalid course_code format: ${courseCode}. Expected: {target_lang}_for_{known_lang}[_suffix]`);
  }
  return {
    target_lang: match[1],
    known_lang: match[2]
  };
}

// =============================================================================
// ANALYSIS: Count what's in the JSON files
// =============================================================================

function analyzeSource(legoPairs, legoBaskets) {
  const counts = {
    seeds: 0,
    legos: 0,
    legos_new: 0,
    legos_not_new: 0,
    legos_a_type: 0,
    legos_m_type: 0,
    lego_components: 0,
    practice_phrases: 0
  };

  // Build set of new lego IDs from lego_pairs
  const newLegoIds = new Set();

  legoPairs.seeds.forEach(seed => {
    counts.seeds++;

    (seed.legos || []).forEach(lego => {
      counts.legos++;

      if (lego.new === true) {
        counts.legos_new++;
        newLegoIds.add(lego.id);
      } else {
        counts.legos_not_new++;
      }

      if (lego.type === 'A') counts.legos_a_type++;
      if (lego.type === 'M') counts.legos_m_type++;

      // Count components (for M-type LEGOs)
      if (lego.components && Array.isArray(lego.components)) {
        counts.lego_components += lego.components.length;
      }
    });
  });

  // Count practice phrases (only for new LEGOs)
  Object.entries(legoBaskets.baskets || {}).forEach(([legoId, basket]) => {
    if (newLegoIds.has(legoId)) {
      counts.practice_phrases += (basket.practice_phrases || []).length;
    }
  });

  return { counts, newLegoIds };
}

// =============================================================================
// IMPORT LOGIC
// =============================================================================

async function importCourse(courseCode, dryRun = false) {
  console.log('='.repeat(70));
  console.log('Import Course to Registry-Aligned Database');
  console.log('='.repeat(70));
  console.log(`Course: ${courseCode}`);
  console.log(`Mode: ${dryRun ? 'DRY RUN' : 'LIVE'}`);
  console.log();

  // ---------------------------------------------------------
  // 1. Load JSON files
  // ---------------------------------------------------------

  const courseDir = path.join(VFS_COURSES, courseCode);
  const legoPairsPath = path.join(courseDir, 'lego_pairs.json');
  const legoBasketsPath = path.join(courseDir, 'lego_baskets.json');

  console.log('Loading input files...');
  if (!await fs.pathExists(legoPairsPath)) {
    throw new Error(`lego_pairs.json not found at ${legoPairsPath}`);
  }
  if (!await fs.pathExists(legoBasketsPath)) {
    throw new Error(`lego_baskets.json not found at ${legoBasketsPath}`);
  }

  const legoPairs = await fs.readJson(legoPairsPath);
  const legoBaskets = await fs.readJson(legoBasketsPath);

  console.log(`  ✓ Loaded lego_pairs.json`);
  console.log(`  ✓ Loaded lego_baskets.json`);
  console.log();

  // ---------------------------------------------------------
  // 2. Analyze source
  // ---------------------------------------------------------

  const { counts: expected, newLegoIds } = analyzeSource(legoPairs, legoBaskets);

  console.log('Source file analysis:');
  console.log(`  Seeds: ${expected.seeds}`);
  console.log(`  LEGOs: ${expected.legos} (${expected.legos_new} new, ${expected.legos_not_new} revisits)`);
  console.log(`    A-type: ${expected.legos_a_type}`);
  console.log(`    M-type: ${expected.legos_m_type}`);
  console.log(`  LEGO Components: ${expected.lego_components}`);
  console.log(`  Practice Phrases: ${expected.practice_phrases}`);
  console.log();

  if (dryRun) {
    console.log('DRY RUN - would insert these counts to database');
    console.log('Run without --dry-run to execute');
    return { expected, actual: null, valid: null };
  }

  // ---------------------------------------------------------
  // 3. Ensure course exists
  // ---------------------------------------------------------

  console.log('Checking course record...');
  const { known_lang, target_lang } = parseLanguagesFromCourseCode(courseCode);

  const { data: courseData, error: courseCheckError } = await supabase
    .from('courses')
    .select('course_code')
    .eq('course_code', courseCode)
    .single();

  if (courseCheckError && courseCheckError.code !== 'PGRST116') {
    throw courseCheckError;
  }

  if (!courseData) {
    console.log(`  Creating course: ${courseCode} (${known_lang} → ${target_lang})`);

    // Default voice configuration (can be updated later)
    const { error: courseInsertError } = await supabase
      .from('courses')
      .insert({
        course_code: courseCode,
        known_lang: known_lang,
        target_lang: target_lang,
        display_name: courseCode.replace(/_/g, ' ').toUpperCase(),
        known_voice: 'en-US-JennyNeural',  // Default - update via admin UI
        target_voice_1: 'es-ES-AlvaroNeural',  // Default - update via admin UI
        target_voice_2: 'es-ES-ElviraNeural',  // Default - update via admin UI
        status: 'draft'
      });

    if (courseInsertError) throw courseInsertError;
    console.log(`  ✓ Course created`);
  } else {
    console.log(`  ✓ Course exists`);
  }
  console.log();

  // ---------------------------------------------------------
  // 4. Import data
  // ---------------------------------------------------------

  const actual = {
    seeds: 0,
    legos: 0,
    lego_components: 0,
    practice_phrases: 0
  };

  console.log('Importing course content...');
  const basketLookup = legoBaskets.baskets || {};

  for (let seedIndex = 0; seedIndex < legoPairs.seeds.length; seedIndex++) {
    const seedData = legoPairs.seeds[seedIndex];
    const seedId = seedData.seed_id;
    const seedNumber = parseSeedNumber(seedId);

    const seedKnown = seedData.seed_pair?.known;
    const seedTarget = seedData.seed_pair?.target;

    if (!seedKnown || !seedTarget) {
      console.warn(`  Warning: Seed ${seedId} missing known/target text - skipping`);
      continue;
    }

    // ---------------------------------------------------------
    // 4a. Insert seed
    // ---------------------------------------------------------

    const { error: seedError } = await supabase
      .from('course_seeds')
      .upsert({
        course_code: courseCode,
        seed_number: seedNumber,
        known_text: seedKnown,
        target_text: seedTarget,
        status: 'draft',
        version: 1
      }, {
        onConflict: 'course_code,seed_number'
      });

    if (seedError) throw seedError;
    actual.seeds++;

    // ---------------------------------------------------------
    // 4b. Insert LEGOs for this seed
    // ---------------------------------------------------------

    const legos = seedData.legos || [];

    for (const lego of legos) {
      const legoIndex = parseLegoIndex(lego.id);
      const legoKnown = lego.lego?.known;
      const legoTarget = lego.lego?.target;

      if (!legoKnown || !legoTarget) {
        console.warn(`  Warning: LEGO ${lego.id} missing known/target text - skipping`);
        continue;
      }

      // Prepare components for M-type LEGOs
      let components = null;
      if (lego.type === 'M' && lego.components && Array.isArray(lego.components)) {
        components = lego.components;  // Store as JSONB array
        actual.lego_components += lego.components.length;
      }

      const { error: legoError } = await supabase
        .from('course_legos')
        .upsert({
          course_code: courseCode,
          seed_number: seedNumber,
          lego_index: legoIndex,
          type: lego.type || 'A',
          is_new: lego.new === true,
          known_text: legoKnown,
          target_text: legoTarget,
          components: components,  // JSONB field (null for A-type)
          status: 'draft',
          version: 1
        }, {
          onConflict: 'course_code,seed_number,lego_index'
        });

      if (legoError) throw legoError;
      actual.legos++;

      // ---------------------------------------------------------
      // 4c. Insert practice phrases (only for new LEGOs)
      // ---------------------------------------------------------

      if (lego.new === true) {
        const basket = basketLookup[lego.id];

        if (basket && basket.practice_phrases) {
          const practicePhrases = basket.practice_phrases;

          for (let position = 0; position < practicePhrases.length; position++) {
            const phrase = practicePhrases[position];

            // Calculate metadata for runtime phrase_type classification
            const wordCount = countWords(phrase.known);
            const legoCount = phrase.lego_count_used || 1;  // Default to 1 if not specified

            const { error: phraseError } = await supabase
              .from('course_practice_phrases')
              .upsert({
                course_code: courseCode,
                seed_number: seedNumber,
                lego_index: legoIndex,
                position: position,
                known_text: phrase.known,
                target_text: phrase.target,
                word_count: wordCount,
                lego_count: legoCount,
                status: 'draft',
                version: 1
              }, {
                onConflict: 'course_code,seed_number,lego_index,position'
              });

            if (phraseError) throw phraseError;
            actual.practice_phrases++;
          }
        }
      }
    }

    // Progress indicator
    if ((seedIndex + 1) % 10 === 0 || seedIndex === legoPairs.seeds.length - 1) {
      console.log(`  Processed ${seedIndex + 1}/${legoPairs.seeds.length} seeds...`);
    }
  }

  console.log();
  console.log('='.repeat(70));
  console.log('VALIDATION');
  console.log('='.repeat(70));

  // ---------------------------------------------------------
  // 5. Validate counts
  // ---------------------------------------------------------

  let valid = true;
  const checks = [
    { name: 'seeds', expected: expected.seeds, actual: actual.seeds },
    { name: 'legos', expected: expected.legos, actual: actual.legos },
    { name: 'lego_components', expected: expected.lego_components, actual: actual.lego_components },
    { name: 'practice_phrases', expected: expected.practice_phrases, actual: actual.practice_phrases }
  ];

  for (const check of checks) {
    const status = check.expected === check.actual ? '✓' : '✗';
    const symbol = check.expected === check.actual ? '✓' : '✗';
    console.log(`  ${check.name}: expected ${check.expected}, got ${check.actual} ${symbol}`);
    if (check.expected !== check.actual) valid = false;
  }

  console.log();

  if (valid) {
    console.log('✓ IMPORT SUCCESSFUL - all counts match');
    console.log();
    console.log('Next steps:');
    console.log('  1. Review data in Supabase dashboard');
    console.log('  2. Update course voice configuration if needed');
    console.log('  3. Update status to "released" when ready');
  } else {
    console.log('✗ IMPORT FAILED - count mismatch!');
    console.log('  Data was written but may be incomplete.');
    console.log('  Consider wiping and re-importing.');
  }

  console.log('='.repeat(70));

  return { expected, actual, valid };
}

// =============================================================================
// CLI
// =============================================================================

async function main() {
  const args = process.argv.slice(2);
  const courseCode = args.find(a => !a.startsWith('--'));
  const dryRun = args.includes('--dry-run');

  if (!courseCode) {
    console.error('Usage: node database/import-course-registry.cjs <course_code> [--dry-run]');
    console.error('');
    console.error('Examples:');
    console.error('  node database/import-course-registry.cjs spa_for_eng_v2 --dry-run');
    console.error('  node database/import-course-registry.cjs spa_for_eng_v2');
    console.error('');
    console.error('Input files required in public/vfs/courses/{course_code}/:');
    console.error('  - lego_pairs.json     (LEGO definitions with is_new flags)');
    console.error('  - lego_baskets.json   (Practice phrases for new LEGOs)');
    process.exit(1);
  }

  if (!process.env.SUPABASE_URL || !process.env.SUPABASE_SERVICE_KEY) {
    console.error('Error: SUPABASE_URL and SUPABASE_SERVICE_KEY must be set in .env');
    console.error('');
    console.error('Add to your .env file:');
    console.error('  SUPABASE_URL=https://your-project.supabase.co');
    console.error('  SUPABASE_SERVICE_KEY=sb_secret_your_key_here');
    process.exit(1);
  }

  try {
    const result = await importCourse(courseCode, dryRun);

    if (!dryRun && result.valid === false) {
      process.exit(1);
    }
  } catch (err) {
    console.error('');
    console.error('ERROR:', err.message);
    if (err.stack) {
      console.error('');
      console.error('Stack trace:');
      console.error(err.stack);
    }
    process.exit(1);
  }
}

main();
